<original_code>
import java.util.*;
import java.io.*;

public class BasicJava
{
   public static void main(String[] args)
   {
      Scanner in = new Scanner(System.in);

      int base = in.nextInt();
      int number = in.nextInt();

      int[] digits = new int[110];

      int count = 0;

      while (number > 0) {
         count++;
         digits[count] = number % base;
         number /= base;
      }

      for (int i = 1; i <= count; i++) {
         if (digits[i] > base / 2) {
            digits[i] = - (digits[i] - base);
            if (i + 1 <= count) {
               digits[i + 1]++;
            } else {
               digits = Arrays.copyOf(digits, digits.length + 1);
               digits[count + 1] = 1;
               count++;
            }
         }
      }

      if (digits[count] == 1) {
         count++;
      }

      for (int i = 1; i <= count; i++) {
         if (digits[i] > 1) {
            System.out.println("NO");
            System.exit(0);
         }
      }

      System.out.println("YES");
      in.close();
   }
}
</original_code>

